entries[353856] = { ["name"] = "Ardenweald Wilderling", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"As anima flows to the distant wealds of Ardenweald once more, the wilderlings awaken and cautiously emerge from their canopy burrows.\"\nCovenant:\nNight Fae\nZone:\nArdenweald" }
entries[353857] = { ["name"] = "Autumnal Wilderling", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"The wilderlings are benevolent, magical creatures of Ardenweald, and are drawn to souls that are strong and pure.\"\nCovenant:\nNight Fae\nVendor:\nElwyn\nZone:\nArdenweald\nCost:\n7500" }
