entries[353859] = { ["name"] = "Summer Wilderling", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Stubborn and rebellious, this wilderling is loyal to very few. But those few are bonded for life.\"\nCovenant:\nNight Fae\nDrop:\nEscaped Wilderling\nZone:\nKorthia" }
