entries[353929] = { ["name"] = "Banshee's Bane", ["text"] = "Unlimited range\nInstant\nSylvanas burdens targets with a ravenous affliction, inflicting 1 Shadow damage every second. This effect stacks. Upon removal, this coalesces into a pool of shadow on the ground. Any player touching the pool gains Banshee's Bane , consuming the pool." }
